<section class="panel"><div class="panel-head"><div><h2><?= \CardPay\Core\View::e($title) ?></h2><p><?= count($rows) ?> مورد</p></div><a class="btn primary small" href="<?= \CardPay\Core\View::e($create) ?>">+ افزودن</a></div><div class="table-wrap"><table><thead><tr><?php foreach($columns as$label):?><th><?= \CardPay\Core\View::e($label) ?></th><?php endforeach;?><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="<?= count($columns)+1 ?>"><div class="empty">هنوز موردی ثبت نشده است.</div></td></tr><?php else:foreach($rows as$row):?><tr><?php foreach($columns as$key=>$label):?><td><?php if($key==='is_active'):?><span class="badge <?= $row[$key]?'success':'neutral' ?>"><?= $row[$key]?'فعال':'غیرفعال' ?></span><?php elseif(in_array($key,['public_key'],true)):?><code><?= \CardPay\Core\View::e($row[$key]) ?></code><?php elseif($key==='card_number_last_four'):?><span dir="ltr">•••• <?= \CardPay\Core\View::e($row[$key]) ?></span><?php elseif(str_ends_with((string)$key,'_at')):?><?= \CardPay\Core\View::e(\CardPay\Core\View::localDate($row[$key]??null,(string)($settings['timezone']??'Asia/Tehran'))) ?><?php else:?><?= \CardPay\Core\View::e($row[$key]??'—') ?><?php endif;?></td><?php endforeach;?><td class="actions"><?php if($kind==='application'):?><a href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/applications/'.$row['id'].'/edit')) ?>">ویرایش</a><a href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/applications/'.$row['id'].'/credentials')) ?>">کلیدها</a><?php elseif($kind==='card'):?><a href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/cards/'.$row['id'].'/edit')) ?>">ویرایش</a><?php elseif($kind==='device'):?><a href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/devices/'.$row['id'].'/setup')) ?>">راه‌اندازی</a><?php elseif($kind==='parser'):?><a href="<?= \CardPay\Core\View::e(\CardPay\Core\Url::to('/admin/parsers/'.$row['id'].'/edit')) ?>">ویرایش</a><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section>
